import axios from "axios";
const arrayMapper = (labelText, labelData, dataSetData) => {
    const getData = ()=>{
        const data = {
            labels: labelData,
            datasets: [
                {
                    label: labelText,
                    data: dataSetData,
                    backgroundColor: ["#000"],
                    fill: false,
                    borderColor: "black",
                    borderWidth: 2,
                },
            ],
        };
        console.log("mapped array");
        console.log(data);
        return data;
    }

    return getData();
    
};

export default arrayMapper();
